23→export { MockAdapter, CodexAdapter, ClaudeAdapter, GlmAdapter } from './adapter.mjs';
24→// SC2: the session tier IS the product surface — constructible from the entry point.
25→export { ClaudeSessionCli, GlmSessionCli } from './claude-session.mjs';
26→export { CodexAppServerCli } from './codex-appserver.mjs';
