52→function localGitEnv() {
53→  const env = {}; for (const [key, value] of Object.entries(process.env)) if (!key.startsWith('GIT_')) env[key] = value;
54→  return { ...env, GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: '/dev/null' };
55→}
56→
57→function localGit(args, cwd, opts = {}) { return execFileSync('git', args, { ...opts, cwd, env: localGitEnv() }); }
58→
59→/** worktree.mjs's real functions wrapped into the coordinator's manager interface. */
60→function worktreeManager(repoRoot, opts = {}) {
61→  return {
62→    async create(taskId) {
63→      const base = await worktreeMod.pinBaseSha(repoRoot, {});
64→      const r = await worktreeMod.createFromBase(repoRoot, taskId, base.sha, { dependencyDirs: opts.workerDependencyDirs ?? [] });
65→      return { path: r.dir, branch: r.branch, baseSha: r.baseSha };
66→    },
67→    async capture(worktreePath, opts = {}) {
68→      return worktreeMod.captureCommit(repoRoot, basename(worktreePath), { vendor: opts.vendor, model: opts.model, effort: opts.effort });
69→    },
70→    async createVerifyWorktree(taskId, sha) {
71→      const r = await worktreeMod.freshVerifySandbox(repoRoot, taskId, sha, { dependencyDirs: opts.verifyDependencyDirs ?? [], sparsePaths: opts.verifySparsePaths ?? [] });
72→      return { path: r.dir ?? r.path };
73→    },
74→    async createBaseVerifyWorktree(taskId, sha) {
75→      const r = await worktreeMod.freshVerifySandbox(repoRoot, `${taskId}-base`, sha, { dependencyDirs: opts.verifyDependencyDirs ?? [], sparsePaths: opts.verifySparsePaths ?? [] });
76→      return { path: r.dir ?? r.path };
77→    },
78→    async changedLines(baseSha, resultSha) {
79→      return worktreeMod.changedLines(repoRoot, baseSha, resultSha);
80→    },
81→    async integrate(sha, opts = {}) {
82→      const strategy = opts.strategy ?? 'ff-only';
83→      if (strategy !== 'ff-only') throw new Error(`unsupported integration strategy: ${strategy}`);
84→      const dirty = localGit(['status', '--porcelain'], repoRoot, { encoding: 'utf8' }).trim();
85→      if (dirty) throw new Error('main checkout is dirty');
86→      const beforeSha = localGit(['rev-parse', 'HEAD'], repoRoot, { encoding: 'utf8' }).trim();
87→      localGit(['merge', '--ff-only', sha], repoRoot, { stdio: 'pipe' });
88→      const afterSha = localGit(['rev-parse', 'HEAD'], repoRoot, { encoding: 'utf8' }).trim();
89→      return { beforeSha, resultSha: sha, afterSha };
90→    },
91→    async stageStructuredIntegration(taskId, sha) {
92→      return worktreeMod.stageStructuredIntegration(repoRoot, taskId, sha, { resolver: opts.structuredMerge });
93→    },
94→    async finalizeStructuredIntegration(stage) { return worktreeMod.finalizeStructuredIntegration(repoRoot, stage); },
95→    async inspectStructuredIntegration(stage) { return worktreeMod.inspectStructuredIntegration(repoRoot, stage); },
96→    async removeStructuredIntegration(stage) { return worktreeMod.removeStructuredIntegration(repoRoot, stage); },
97→    async retainResult(sha) {
98→      const ref = `refs/baton/results/${sha}`;
99→      localGit(['update-ref', ref, sha], repoRoot, { stdio: 'ignore' });
100→      return ref;
101→    },
102→    async releaseResult(ref) {
103→      localGit(['update-ref', '-d', ref], repoRoot, { stdio: 'ignore' });
104→    },
105→    async removeVerifyWorktree(verifyPath) {
106→      try { localGit(['worktree', 'remove', '--force', verifyPath], repoRoot, { stdio: 'ignore' }); } catch { /* noop */ }
107→      try { rmSync(verifyPath, { recursive: true, force: true }); } catch { /* noop */ }
108→    },
109→    // Terminal policy cleanup owns non-evidence task branches as well as their checkout/metadata.
110→    async remove(taskId) { try { await worktreeMod.reap(repoRoot, taskId, { force: true, deleteBranch: true }); } catch { /* noop */ } },
111→    async validateSessionContext(context) {
112→      try {
113→        if (!existsSync(context.worktree)) return { ok: false, reason: 'session worktree no longer exists' };
114→        const root = realpathSync(repoRoot);
115→        const worktree = realpathSync(context.worktree);
116→        const managedRoot = realpathSync(join(repoRoot, '.baton', 'wt'));
117→        if (context.repoRoot && realpathSync(context.repoRoot) !== root) return { ok: false, reason: 'session repository identity mismatch' };
118→        if (worktree !== managedRoot && !worktree.startsWith(`${managedRoot}${sep}`)) return { ok: false, reason: 'session worktree is outside Baton ownership' };
119→        if (context.ownerTaskId && basename(worktree) !== context.ownerTaskId) return { ok: false, reason: 'session worktree owner mismatch' };
120→        const top = localGit(['rev-parse', '--show-toplevel'], worktree, { encoding: 'utf8' }).trim();
121→        if (realpathSync(top) !== worktree) return { ok: false, reason: 'session path is not the recorded git worktree root' };
122→        if (context.branch) {
123→          const branch = localGit(['branch', '--show-current'], worktree, { encoding: 'utf8' }).trim();
124→          if (branch !== context.branch) return { ok: false, reason: 'session worktree branch mismatch' };
125→        }
126→        if (context.baseSha) {
127→          localGit(['merge-base', '--is-ancestor', context.baseSha, 'HEAD'], worktree, { stdio: 'ignore' });
128→        }
129→        return { ok: true };
130→      } catch (err) {
131→        return { ok: false, reason: `session context validation failed: ${err?.message ?? err}` };
132→      }
133→    },
134→    async reconcile() { try { return await worktreeMod.reconcile(repoRoot, []); } catch { return null; } },
135→  };
136→}
137→
138→/** The real hardened referee in the coordinator's fn contract (maps task.worktree -> workerWorktreeDir, string sandbox -> {dir}). */
139→function refereeFn(task, result, opts) {
140→  const mapped = { ...task, workerWorktreeDir: task.worktree, verification: opts.pinnedVerification };
141→  return verify(mapped, result, { dir: opts.sandbox }, {
142→    ...(opts.baseSandbox ? { baseSandbox: { dir: opts.baseSandbox } } : {}),
143→  });
144→}
145→
146→/**
147→ * Assemble a runnable fleet driver.
148→ * @param {{repoRoot:string, logDir:string, adapters:Record<string,object>, now?:()=>number,
149→ *          approvalTimeoutMs?:number, stopDeadlineMs?:number}} opts
150→ * @returns {{coordinator:Coordinator, story:StoryCompiler, router:AdaptiveRouter, log:Log}}
151→ */
152→export function createDriver(opts) {
153→  const now = opts.now ?? Date.now;
154→  const log = new Log(opts.logDir, () => new Date(now()).toISOString());
155→  const fences = new FenceTable();
156→  const router = new AdaptiveRouter({ mode: 'adaptive', now });
157→  const story = new StoryCompiler({ now });
158→  const runtimeScopes = opts.runtimeScopes ?? new RuntimeIsolation({
159→    repoRoot: opts.repoRoot,
160→    ...(opts.runtimeIsolation ?? {}),
161→  });
162→  const coordination = opts.coordination ?? new CoordinationStore(join(opts.logDir, 'coordination'), {
163→    operationalRead: (worker, seq) => log.read(worker, seq).find((event) => event.seq === seq) ?? null,
164→  });
165→  const publisher = Object.hasOwn(opts, 'publisher') ? opts.publisher : async ({ remote, ref, sha }) => {
166→    execFileSync('git', ['push', '--porcelain', remote, `${sha}:${ref}`], { cwd: opts.repoRoot, stdio: 'ignore' });
167→    return { transport: 'git-push' };
168→  };
169→
170→  // C2/D5: real selection via router.pick(task, candidates) over the ceiling-feasible
171→  // set — no first-fit fallback. `pick()` already returns null when nothing is eligible,
172→  // which is exactly "queue" (the coordinator's own ceiling re-check catches it too).
173→  const route = (task, cards, inFlight) => {
174→    // `cards` is already the coordinator's exact model/effort/session/policy-filtered
175→    // candidate set. Re-expanding from every registered adapter would resurrect rejected
176→    // candidates and dereference absent cards in heterogeneous fleets.
177→    let feasible = Object.keys(cards).filter((v) => (inFlight[v] ?? 0) < cards[v].concurrencyCeiling);
178→    // SC7: the explicit capability tag beats operator folklore — when any feasible card lists
179→    // the task's taskType in nonRefuserFor, restrict to those vendors. Feasibility is computed
180→    // FIRST (a capable-but-saturated vendor never restricts) and an unlisted taskType leaves
181→    // the pool untouched — the restriction can never strand a task.
182→    const capable = feasible.filter((v) => Array.isArray(cards[v].nonRefuserFor) && cards[v].nonRefuserFor.includes(task.taskType));
183→    if (capable.length > 0) feasible = capable;
184→    const candidateKey = (v) => {
185→      return routeTupleKey(cards[v], cards[v].modelSelection?.resolved, cards[v].modelSelection?.resolvedEffort, task.taskType);
186→    };
187→    const candidates = feasible.map((v) => ({
188→      modelVersion: candidateKey(v),
189→      // Read-only migration aliases for router state written before the full
190→      // harness/model/effort tuple became the canonical learning identity.
191→      legacyModelVersions: [
192→        ...(cards[v].modelSelection?.resolved
193→          ? [`${cards[v].harness}@${cards[v].version}#${cards[v].modelSelection.resolved}`]
194→          : []),
195→        `${cards[v].harness}@${cards[v].version}`,
196→      ],
197→      family: cards[v].modelSelection?.family ?? 'default',
198→      concurrencyCeiling: cards[v].concurrencyCeiling,
199→      inFlight: inFlight[v] ?? 0,
200→    }));
201→    const chosen = router.pick(task, candidates);
202→    if (!chosen) return null;
203→    // First-listed feasible vendor wins a modelVersion collision: two adapters CAN share
204→    // harness@version (e.g. one-shot ClaudeCli and session ClaudeSessionCli for the same CLI),
205→    // and a last-wins Map would silently flip which vendor key receives the dispatch.
206→    return feasible.find((v) => candidateKey(v) === chosen) ?? null;
207→  };
208→  route.record = (mv, tt, win) => router.record(mv, tt, win);
209→
210→  const coordinator = new Coordinator({
211→    log, fences,
212→    adapters: opts.adapters,
213→    worktrees: worktreeManager(opts.repoRoot, {
214→      workerDependencyDirs: opts.workerDependencyDirs,
215→      verifyDependencyDirs: opts.verifyDependencyDirs,
216→      verifySparsePaths: opts.verifySparsePaths,
217→      structuredMerge: opts.structuredMerge,
218→    }),
219→    runtimeScopes,
220→    coordination,
221→    repoRoot: opts.repoRoot,
222→    referee: refereeFn,
223→    route,
224→    accept: (verdict, acceptOpts) => accept(verdict, acceptOpts),
225→    acceptOpts: {
226→      requireRedGreen: opts.requireRedGreen ?? false,
227→      requireCoverage: opts.requireCoverage ?? false,
228→      requireMutation: opts.requireMutation ?? false,
229→    },
230→    requireIndependentOracle: opts.requireIndependentOracle ?? false,
231→    publisher,
232→    story: { record: (e) => story.ingest(e) },
233→    now,
234→    approvalTimeoutMs: opts.approvalTimeoutMs ?? 60000,
235→    stopDeadlineMs: opts.stopDeadlineMs ?? 15000,
236→    recoveryTimeoutMs: opts.recoveryTimeoutMs ?? 15000,
237→    budgetPolicy: opts.budgetPolicy,
238→    watchdog: opts.watchdog,
239→  });
240→
241→  return { coordinator, story, router, log, coordination };
242→}
